options(stringsAsFactors = FALSE)
stopifnot(getRversion() == "4.6.1")
root <- normalizePath(getwd(), mustWork = TRUE)
out <- file.path(root, "audit/manuscript_nature_health/revision_2026_09_11/consolidated_display_repair_order72k")
record <- file.path(out, "environment_capture_recovery_001")
capture <- file.path(out, "capture_s2_attempt3")
stopifnot(!file.exists(file.path(record, "capture_reconciled_checks.csv")))
sha <- function(p) { con <- file(p, "rb"); on.exit(close(con)); unname(unclass(as.character(openssl::sha256(con)))) }
raw <- xml2::read_html(file.path(root, "audit/manuscript_nature_health/figure_table_selection_assets/tbl-near-eye-metrics.html"))
rendered <- xml2::read_html(file.path(capture, "supp_table_s2_source.html"))
manifest <- jsonlite::fromJSON(file.path(capture, "word_table_png_manifest.json"), simplifyVector = FALSE)[[1]]
parts <- lapply(manifest$files, function(x) xml2::read_html(sub("\\.png$", ".html", x$path)))
cells <- function(doc) unname(vapply(xml2::xml_find_all(doc, ".//tbody/tr/*"), xml2::xml_text, character(1)))
compact <- function(x) gsub("[[:space:]]+", " ", trimws(x))
out_cells <- unlist(lapply(parts, cells), use.names = FALSE)
raw_cells <- cells(raw); rendered_cells <- cells(rendered)
stopifnot(length(raw_cells) == length(rendered_cells), length(raw_cells) == length(out_cells))
differences <- data.frame(cell = seq_along(raw_cells), frozen_fragment = raw_cells, frozen_render = rendered_cells, capture = out_cells, rendered_to_capture_exact = rendered_cells == out_cells, fragment_to_capture_whitespace_only = compact(raw_cells) == compact(out_cells))
write.csv(differences, file.path(record, "all_cell_text_comparison.csv"), row.names = FALSE)
header <- function(x) xml2::xml_text(xml2::xml_find_first(x, ".//thead"))
footer <- function(x) xml2::xml_text(xml2::xml_find_first(x, ".//tfoot"))
checks <- data.frame(check = c("every_frozen_render_cell_raw_exact", "every_original_fragment_cell_equal_after_HTML_whitespace_normalization", "headers_raw_exact_to_frozen_render", "headers_whitespace_equal_to_original_fragment", "last_notes_raw_exact_to_frozen_render", "last_notes_whitespace_equal_to_original_fragment"), pass = c(all(differences$rendered_to_capture_exact), all(differences$fragment_to_capture_whitespace_only), all(vapply(parts, function(x) identical(header(x), header(rendered)), logical(1))), all(vapply(parts, function(x) identical(compact(header(x)), compact(header(raw))), logical(1))), identical(footer(parts[[3]]), footer(rendered)), identical(compact(footer(parts[[3]])), compact(footer(raw)))))
write.csv(checks, file.path(record, "capture_reconciled_checks.csv"), row.names = FALSE)
stopifnot(all(checks$pass))
files <- list.files(capture, full.names = TRUE)
write.csv(data.frame(path = files, sha256 = vapply(files, sha, character(1)), bytes = file.info(files)$size), file.path(record, "attempt3_output_pins.csv"), row.names = FALSE)
writeLines(c("Exact text/payload preservation is separate from the failed visual check.", "The earlier raw comparison against unrendered HTML counted indentation/newline normalization as content changes. That failed checker record is retained. The stricter route comparison here additionally requires character-exact equality to the immutable browser-source extraction, plus whitespace-only equivalence to the original fragment.", capture.output(sessionInfo())), file.path(record, "reconciliation_session.txt"))
cat("PASS: 244 cells exact to frozen rendered source; original fragment, complete headers and notes differ only in HTML whitespace. Visual FAIL remains.\n")
